commands:
make check 2>&1 | tail -3; make lint 2>&1 | tail -1; awk 'length > 60 {print FILENAME": "FNR": "length}' hourglass/gaps.py tests/test_gaps.py hourglass/errors.py; awk 'prev=="" && $0=="" {print FILENAME": double blank at "FNR} {prev=$0}' hourglass/gaps.py tests/test_gaps.py; python3 -I -c "
import ast, sys
for path in sys.argv[1:]:
    tree = ast.parse(open(path).read())
    for node in ast.walk(tree):
        if isinstance(node, ast.FunctionDef):
            print(path, node.name, node.end_lineno - node.lineno + 1)
        if isinstance(node, ast.Name) and isinstance(node.ctx, ast.Store) and len(node.id) < 4:
            print('SHORT', path, node.id, node.lineno)
        if isinstance(node, ast.arg) and len(node.arg) < 4:
            print('SHORT ARG', path, node.arg, node.lineno)
" hourglass/gaps.py tests/test_gaps.py; grep -n '&&' hourglass/gaps.py tests/test_gaps.py; echo checks-done

make check 2>&1 | tail -3; make lint 2>&1 | tail -1; python3 -I -c "
